CREATE TYPE public.app_role AS ENUM ('admin', 'student');
CREATE TABLE public.profiles (user_id uuid PRIMARY KEY, display_name text NOT NULL DEFAULT '', avatar_url text, phone text, preferences jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL DEFAULT 'student', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE TABLE public.courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Technology', difficulty text NOT NULL DEFAULT 'Beginner' CHECK (difficulty IN ('Beginner','Intermediate','Advanced')), duration_hours integer NOT NULL DEFAULT 0, instructor text NOT NULL DEFAULT 'NEURA Faculty', thumbnail_url text, learning_objectives jsonb NOT NULL DEFAULT '[]'::jsonb, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.courses TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.courses TO authenticated; GRANT ALL ON public.courses TO service_role; ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.course_modules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(course_id, sort_order));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.course_modules TO authenticated; GRANT ALL ON public.course_modules TO service_role; ALTER TABLE public.course_modules ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','completed','paused')), enrolled_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(user_id, course_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.enrollments TO authenticated; GRANT ALL ON public.enrollments TO service_role; ALTER TABLE public.enrollments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_id uuid NOT NULL REFERENCES public.course_modules(id) ON DELETE CASCADE, title text NOT NULL, summary text NOT NULL DEFAULT '', content text NOT NULL DEFAULT '', content_type text NOT NULL DEFAULT 'text' CHECK(content_type IN ('video','pdf','text','link','resource')), video_url text, sort_order integer NOT NULL DEFAULT 0, duration_minutes integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(module_id,sort_order));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.lessons TO authenticated; GRANT ALL ON public.lessons TO service_role; ALTER TABLE public.lessons ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.lesson_resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid NOT NULL REFERENCES public.lessons(id) ON DELETE CASCADE, title text NOT NULL, file_path text, external_url text, file_type text NOT NULL DEFAULT 'link', file_size_bytes bigint, downloadable boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.lesson_resources TO authenticated; GRANT ALL ON public.lesson_resources TO service_role; ALTER TABLE public.lesson_resources ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.lesson_progress (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, lesson_id uuid NOT NULL REFERENCES public.lessons(id) ON DELETE CASCADE, completed boolean NOT NULL DEFAULT false, last_position_seconds integer NOT NULL DEFAULT 0, completed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,lesson_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.lesson_progress TO authenticated; GRANT ALL ON public.lesson_progress TO service_role; ALTER TABLE public.lesson_progress ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid REFERENCES public.courses(id) ON DELETE SET NULL, prompt text NOT NULL, explanation text NOT NULL DEFAULT '', difficulty text NOT NULL DEFAULT 'Medium' CHECK(difficulty IN ('Easy','Medium','Hard')), topic text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.questions TO authenticated; GRANT ALL ON public.questions TO service_role; ALTER TABLE public.questions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.question_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE, label text NOT NULL, is_correct boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, UNIQUE(question_id,sort_order));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.question_options TO authenticated; GRANT ALL ON public.question_options TO service_role; ALTER TABLE public.question_options ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.tests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', instructions text NOT NULL DEFAULT '', duration_minutes integer NOT NULL DEFAULT 30, passing_percentage numeric(5,2) NOT NULL DEFAULT 70, published boolean NOT NULL DEFAULT false, shuffle_questions boolean NOT NULL DEFAULT false, shuffle_options boolean NOT NULL DEFAULT false, allow_review boolean NOT NULL DEFAULT true, max_attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tests TO authenticated; GRANT ALL ON public.tests TO service_role; ALTER TABLE public.tests ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.test_questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), test_id uuid NOT NULL REFERENCES public.tests(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE, points numeric(7,2) NOT NULL DEFAULT 1, sort_order integer NOT NULL DEFAULT 0, UNIQUE(test_id,question_id), UNIQUE(test_id,sort_order));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.test_questions TO authenticated; GRANT ALL ON public.test_questions TO service_role; ALTER TABLE public.test_questions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.test_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, test_id uuid NOT NULL REFERENCES public.tests(id) ON DELETE CASCADE, attempt_number integer NOT NULL DEFAULT 1, started_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz, time_taken_seconds integer, score numeric(8,2), max_score numeric(8,2), percentage numeric(5,2), passed boolean, correct_count integer, incorrect_count integer, unanswered_count integer, status text NOT NULL DEFAULT 'in_progress' CHECK(status IN ('in_progress','submitted','expired')), UNIQUE(user_id,test_id,attempt_number));
GRANT SELECT, INSERT, UPDATE ON public.test_attempts TO authenticated; GRANT ALL ON public.test_attempts TO service_role; ALTER TABLE public.test_attempts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.test_answers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES public.test_attempts(id) ON DELETE CASCADE, question_id uuid NOT NULL REFERENCES public.questions(id) ON DELETE CASCADE, option_id uuid REFERENCES public.question_options(id) ON DELETE SET NULL, is_correct boolean, points_awarded numeric(7,2), marked_for_review boolean NOT NULL DEFAULT false, UNIQUE(attempt_id,question_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.test_answers TO authenticated; GRANT ALL ON public.test_answers TO service_role; ALTER TABLE public.test_answers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.certificates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, certificate_code text NOT NULL UNIQUE DEFAULT upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)), issued_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,course_id));
GRANT SELECT, INSERT ON public.certificates TO authenticated; GRANT ALL ON public.certificates TO service_role; ALTER TABLE public.certificates ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT '', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.platform_settings (setting_key text PRIMARY KEY, setting_value jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.platform_settings TO authenticated; GRANT ALL ON public.platform_settings TO service_role; ALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Profile owner or admin read" ON public.profiles FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Users create own profile" ON public.profiles FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY "Profile owner or admin update" ON public.profiles FOR UPDATE TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "User role visibility" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Public published courses" ON public.courses FOR SELECT TO anon USING (published = true);
CREATE POLICY "Authenticated published courses" ON public.courses FOR SELECT TO authenticated USING (published = true OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin course management" ON public.courses FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Published course modules" ON public.course_modules FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.courses c WHERE c.id=course_id AND c.published=true) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin module management" ON public.course_modules FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Enrollment owner read" ON public.enrollments FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Enroll in published course" ON public.enrollments FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.courses c WHERE c.id=course_id AND c.published=true));
CREATE POLICY "Admin enrollment management" ON public.enrollments FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Enrolled lesson access" ON public.lessons FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR EXISTS (SELECT 1 FROM public.course_modules m JOIN public.enrollments e ON e.course_id=m.course_id WHERE m.id=module_id AND e.user_id=auth.uid() AND e.status='active'));
CREATE POLICY "Admin lesson management" ON public.lessons FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Enrolled resources access" ON public.lesson_resources FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR EXISTS (SELECT 1 FROM public.lessons l JOIN public.course_modules m ON m.id=l.module_id JOIN public.enrollments e ON e.course_id=m.course_id WHERE l.id=lesson_id AND e.user_id=auth.uid() AND e.status='active'));
CREATE POLICY "Admin resource management" ON public.lesson_resources FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Owner progress access" ON public.lesson_progress FOR ALL TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin question bank" ON public.questions FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin option keys" ON public.question_options FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Published enrolled test access" ON public.tests FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR (published=true AND EXISTS (SELECT 1 FROM public.enrollments e WHERE e.course_id=course_id AND e.user_id=auth.uid() AND e.status='active')));
CREATE POLICY "Admin test management" ON public.tests FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin test question management" ON public.test_questions FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin question option access" ON public.question_options FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Attempt owner or admin read" ON public.test_attempts FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Owner starts enrolled test" ON public.test_attempts FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND EXISTS (SELECT 1 FROM public.tests t JOIN public.enrollments e ON e.course_id=t.course_id WHERE t.id=test_id AND t.published=true AND e.user_id=auth.uid() AND e.status='active'));
CREATE POLICY "Owner updates active attempt" ON public.test_attempts FOR UPDATE TO authenticated USING (user_id=auth.uid() AND status='in_progress') WITH CHECK (user_id=auth.uid());
CREATE POLICY "Admin attempt management" ON public.test_attempts FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Attempt answer read" ON public.test_answers FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.test_attempts a WHERE a.id=attempt_id AND (a.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY "Own active answer insert" ON public.test_answers FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.test_attempts a WHERE a.id=attempt_id AND a.user_id=auth.uid() AND a.status='in_progress'));
CREATE POLICY "Own active answer update" ON public.test_answers FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.test_attempts a WHERE a.id=attempt_id AND a.user_id=auth.uid() AND a.status='in_progress')) WITH CHECK (EXISTS (SELECT 1 FROM public.test_attempts a WHERE a.id=attempt_id AND a.user_id=auth.uid() AND a.status='in_progress'));
CREATE POLICY "Admin answer management" ON public.test_answers FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Certificate owner read" ON public.certificates FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin certificate issue" ON public.certificates FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Own notification read" ON public.notifications FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "Own notification update" ON public.notifications FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY "Admin audit visibility" ON public.audit_logs FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Own audit append" ON public.audit_logs FOR INSERT TO authenticated WITH CHECK (actor_id=auth.uid());
CREATE POLICY "Admin settings management" ON public.platform_settings FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(user_id,display_name) VALUES (NEW.id,COALESCE(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name','')) ON CONFLICT(user_id) DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'student') ON CONFLICT(user_id,role) DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER on_auth_user_created_neura AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE INDEX courses_published_category_idx ON public.courses(published,category);
CREATE INDEX modules_course_sort_idx ON public.course_modules(course_id,sort_order);
CREATE INDEX lessons_module_sort_idx ON public.lessons(module_id,sort_order);
CREATE INDEX enrollments_user_status_idx ON public.enrollments(user_id,status);
CREATE INDEX lesson_progress_user_idx ON public.lesson_progress(user_id,completed);
CREATE INDEX tests_course_published_idx ON public.tests(course_id,published);
CREATE INDEX attempts_user_test_idx ON public.test_attempts(user_id,test_id,started_at DESC);
CREATE INDEX test_answers_attempt_idx ON public.test_answers(attempt_id);